pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(uint256 id) public {
        // Any id is admissible: a token that was never minted must have no owner.
        // General rule: for every id without a live owner, ownerOf(id) must revert
        // (the token registry holds no stale owner for unminted/burned tokens).
        bool ok = true;
        try c.ownerOf(id) {
            ok = false;
        } catch {
            ok = true;
        }
        assertTrue(ok, "ownerOf must not return an owner for a token with no owner");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(address actor, uint256 id) public {
        // keep the admissible domain wide: any non-sentinel actor, any id
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(0xdead));

        // attempt to burn token `id` by transferring it to the dead address.
        // Only `actor` (its owner) or an approved party can do this; we act as `actor`.
        vm.prank(actor);
        bool transferred;
        try c.transferFrom(actor, address(0xdead), id) {
            transferred = true;
        } catch {
            transferred = false;
        }

        // A completed burn must leave NO owner recorded for `id`:
        // ownerOf(id) must revert (or return the zero address) afterwards.
        // The buggy version keeps the stale owner in _ownerOf, so ownerOf(id)
        // still returns `actor` after the burn completed, violating the rule.
        bool owned;
        try c.ownerOf(id) returns (address o) {
            owned = (o != address(0));
        } catch {
            owned = false;
        }

        assertTrue(!(transferred && owned));
    }
}
